test('keeps only adults', () => { assert.deepEqual(adultNames([{ name: 'Asha', age: 31 }, { name: 'Ben', age: 12 }, { name: 'Chen', age: 45 }]), ['Asha', 'Chen']); });
test('18 counts as an adult', () => { assert.deepEqual(adultNames([{ name: 'Dee', age: 18 }, { name: 'Eli', age: 17 }]), ['Dee']); });
test('nobody qualifies', () => { assert.deepEqual(adultNames([{ name: 'Fay', age: 9 }]), []); });
test('empty input', () => { assert.deepEqual(adultNames([]), []); });

referenceSolution:
function adultNames(people) {
  const names = [];
  for (const person of people) {
    if (person.age >= 18) {
      names.push(person.name);
    }
  }
  return names;
}
